[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-01)" = 'reminder to x: aoi 2026-01-01 10:00-11:00' ] || { echo "a day with a booking"; fail=1; }
[ -z "$(bash src/remind.sh 2>/dev/null)" ] || { echo "usage should go to stderr"; fail=1; }

